def sql(
    self, dialect: DialectType = None, copy: bool = True, **opts: Unpack[GeneratorNoDialectArgs]
) -> str:
    from sqlglot.dialects.dialect import Dialect

    return Dialect.get_or_raise(dialect).generate(self, copy=copy, **opts)

def transform(
    self, fun: t.Callable[..., T], *args: object, copy: bool = True, **kwargs: object
) -> T:
    root: t.Any = None
    new_node: t.Any = None

    for node in (self.copy() if copy else self).dfs(prune=lambda n: n is not new_node):
        parent, arg_key, index = node.parent, node.arg_key, node.index
        new_node = fun(node, *args, **kwargs)

        if not root:
            root = new_node
        elif parent and arg_key and new_node is not node:
            parent.set(arg_key, new_node, index)

    assert root
    return root

def walk(
    self, bfs: bool = True, prune: t.Callable[[Expr], bool] | None = None
) -> Iterator[Expr]:
    if bfs:
        yield from self.bfs(prune=prune)
    else:
        yield from self.dfs(prune=prune)

def find_all(self, *expression_types: Type[E], bfs: bool = True) -> Iterator[E]:
    for expression in self.walk(bfs=bfs):
        if isinstance(expression, expression_types):
            yield expression

def generate(
    self, expression: exp.Expr, copy: bool = True, **opts: Unpack[GeneratorArgs]
) -> str:
    return self.generator(**opts).generate(expression, copy=copy)

def tokenize(self, sql: str) -> list[Token]:
    """Returns a list of tokens corresponding to the SQL string `sql`."""
    return self._core.tokenize(sql)  # type: ignore
